typedef long PBB_Fixed;
#define PBB_FIXED_SHIFT 16
#define PBB_FIXED_ONE ((PBB_Fixed)1L << PBB_FIXED_SHIFT)
#define PBB_FIXED_HALF (PBB_FIXED_ONE >> 1)
#define PBB_FIXED_FROM_INT(v) ((PBB_Fixed)(v) << PBB_FIXED_SHIFT)
#define PBB_FIXED_TO_INT(v) ((int)((v) >> PBB_FIXED_SHIFT))

